"use client";

import { useState } from "react";
import { Check } from "lucide-react";
import { market } from "@/lib/market/provider";
import { ORDER_FEE, previewOrder, type Side, type Transaction } from "@/lib/trading/engine";
import { useAccount, useAccountStore } from "@/lib/trading/store";
import { useNow } from "@/lib/ui/clock";
import { money, price as fmtPrice, qty as fmtQty } from "@/lib/ui/format";
import { Sheet } from "./sheet";
import { AssetAvatar, Button } from "./ui";

type Mode = "amount" | "quantity";

export function TradeSheet({
  symbol,
  open,
  side: initialSide,
  onClose,
}: {
  symbol: string;
  open: boolean;
  side: Side;
  onClose: () => void;
}) {
  // Remount the form each time the sheet opens so it starts clean.
  return (
    <Sheet open={open} onClose={onClose}>
      {open && <TradeForm key={`${symbol}-${initialSide}`} symbol={symbol} initialSide={initialSide} onClose={onClose} />}
    </Sheet>
  );
}

function TradeForm({ symbol, initialSide, onClose }: { symbol: string; initialSide: Side; onClose: () => void }) {
  const now = useNow();
  const account = useAccount();
  const placeOrder = useAccountStore((s) => s.placeOrder);
  const asset = market.getAsset(symbol)!;
  const livePrice = market.priceAt(symbol, now);
  const held = account.positions[symbol]?.quantity ?? 0;

  const [side, setSide] = useState<Side>(held > 0 ? initialSide : "buy");
  const [mode, setMode] = useState<Mode>("amount");
  const [input, setInput] = useState("");
  const [done, setDone] = useState<Transaction | null>(null);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const value = Number(input.replace(",", "."));
  const preview = input ? previewOrder(account, { symbol, side, mode, value }, livePrice) : null;

  const quick =
    side === "buy"
      ? [50, 100, 250, 500].map((v) => ({ label: `€${v}`, set: () => (setMode("amount"), setInput(String(v)) ) }))
      : [0.25, 0.5, 1].map((f) => ({
          label: f === 1 ? "All" : `${f * 100}%`,
          set: () => (setMode("quantity"), setInput(String(Math.floor(held * f * 1e6) / 1e6))),
        }));

  function submit() {
    const r = placeOrder({ symbol, side, mode, value });
    if (r.ok) setDone(r.value);
    else setSubmitError(r.error);
  }

  if (done) {
    return (
      <div className="flex flex-col items-center gap-3 py-6 text-center">
        <span className="grid size-16 place-items-center rounded-full bg-gain/15 text-gain">
          <Check size={32} strokeWidth={3} />
        </span>
        <p className="text-xl font-semibold">{done.type === "buy" ? "Bought" : "Sold"} {fmtQty(done.quantity!)} {asset.symbol}</p>
        <p className="text-sm text-muted">
          at {fmtPrice(done.price!)} · {money(done.amount)} + {money(done.fee)} fee
        </p>
        <Button className="mt-4 w-full" onClick={onClose}>
          Done
        </Button>
      </div>
    );
  }

  const error = submitError ?? (preview && !preview.ok ? preview.error : null);

  return (
    <div className="flex flex-col gap-5">
      <div className="flex items-center gap-3">
        <AssetAvatar asset={asset} size={36} />
        <div className="min-w-0 flex-1">
          <p className="font-semibold">{asset.name}</p>
          <p className="tabular text-sm text-muted">{fmtPrice(livePrice)} per unit</p>
        </div>
        <div className="flex rounded-full bg-surface-2 p-1 text-sm font-semibold">
          {(["buy", "sell"] as const).map((s) => (
            <button
              key={s}
              disabled={s === "sell" && held <= 0}
              onClick={() => (setSide(s), setInput(""), setSubmitError(null))}
              className={`rounded-full px-4 py-1.5 capitalize transition disabled:opacity-30 ${
                side === s ? (s === "buy" ? "bg-gain text-black" : "bg-loss text-white") : "text-muted"
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      <div className="rounded-2xl bg-surface-2 p-4">
        <div className="mb-2 flex items-center justify-between text-xs text-muted">
          <span>{mode === "amount" ? "Amount in EUR" : `Number of ${asset.symbol}`}</span>
          <button
            className="font-semibold text-accent"
            onClick={() => (setMode(mode === "amount" ? "quantity" : "amount"), setInput(""))}
          >
            Switch to {mode === "amount" ? "units" : "EUR"}
          </button>
        </div>
        <div className="flex items-baseline gap-2">
          {mode === "amount" && <span className="text-3xl font-semibold text-muted">€</span>}
          <input
            data-autofocus
            inputMode="decimal"
            placeholder="0"
            value={input}
            onChange={(e) => (setInput(e.target.value.replace(/[^0-9.,]/g, "")), setSubmitError(null))}
            onKeyDown={(e) => e.key === "Enter" && preview?.ok && submit()}
            className="tabular w-full bg-transparent text-4xl font-semibold outline-none placeholder:text-line"
          />
        </div>
        <div className="mt-3 flex flex-wrap gap-2">
          {quick.map((q) => (
            <button key={q.label} onClick={q.set} className="rounded-full border border-line px-3 py-1 text-xs font-semibold text-muted hover:text-fg">
              {q.label}
            </button>
          ))}
        </div>
      </div>

      <dl className="flex flex-col gap-2 text-sm">
        <Row label={side === "buy" ? "Available cash" : `You own`}>
          {side === "buy" ? money(account.cash) : `${fmtQty(held)} ${asset.symbol}`}
        </Row>
        <Row label="Estimated units">{preview?.ok ? fmtQty(preview.value.quantity) : "—"}</Row>
        <Row label="Order fee">{money(ORDER_FEE)}</Row>
        <Row label={side === "buy" ? "Total cost" : "You receive"} strong>
          {preview?.ok ? money(preview.value.net) : "—"}
        </Row>
      </dl>

      {error && <p className="-mt-2 text-sm font-medium text-loss">{error}</p>}

      <Button variant={side === "buy" ? "gain" : "loss"} className="w-full py-4 text-base" disabled={!preview?.ok} onClick={submit}>
        {side === "buy" ? "Buy" : "Sell"} {asset.symbol}
      </Button>
      <p className="-mt-2 text-center text-xs text-muted">Market order · simulated execution at the live simulated price</p>
    </div>
  );
}

function Row({ label, children, strong }: { label: string; children: React.ReactNode; strong?: boolean }) {
  return (
    <div className="flex justify-between">
      <dt className="text-muted">{label}</dt>
      <dd className={`tabular ${strong ? "font-semibold text-fg" : ""}`}>{children}</dd>
    </div>
  );
}
